def _run():
    JOBS[job_id]["status"] = "running"
    try:
        for event in run_pipeline(audio_path=str(audio_path), lyrics=lyrics,
                output_dir=str(DATA_DIR), job_id=job_id, style=style, ...):
            JOBS[job_id]["events"].append(event)
            stage = event.get("stage", "")
            if stage == "done":
                JOBS[job_id]["status"] = "done"
                JOBS[job_id]["output_path"] = event.get("output")
            elif stage == "error":
                JOBS[job_id]["status"] = "error"; JOBS[job_id]["error"] = event.get("message")
    except Exception as e:
        JOBS[job_id]["status"] = "error"; JOBS[job_id]["error"] = str(e)

threading.Thread(target=_run, daemon=True).start()
return {"job_id": job_id, "status": "queued"}

# Try bracket markers: [Verse 1], [Chorus], etc.
pattern = r'\[([^\]]+)\]([^\[]*)'
matches = re.findall(pattern, lyrics, re.DOTALL | re.IGNORECASE)
if matches:
    segments = [(_normalize_label(label), text.strip())
                for label, text in matches if text.strip()]
    if segments:
        return segments

# Try double-newline paragraphs
paragraphs = [p.strip() for p in re.split(r'\n\s*\n', lyrics) if p.strip()]
if len(paragraphs) >= 2:
    return list(zip(_auto_label(paragraphs), paragraphs))

# Last resort: ~4-line chunks
lines = [l for l in lyrics.splitlines() if l.strip()]
chunks = ["\n".join(lines[i:i+4]) for i in range(0, len(lines), 4)]
return list(zip(_auto_label(chunks), chunks))

def _fallback_prompt(lyrics_text: str, style_mod: str) -> dict:
    lines = [l.strip() for l in lyrics_text.splitlines() if l.strip()][:2]
    base = " ".join(lines)[:120]
    return {
        "prompt": f"A visual scene inspired by the lyrics '{base}', {style_mod}",
        "mood": "neutral",
        "color_palette": "natural tones",
    }
